with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'シャロットの女', 'ジョン・ウィリアム・ウォーターハウス', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/John_William_Waterhouse_-_The_Lady_of_Shalott_-_Google_Art_Project_%28derivative_work_-_AutoContrast_edit_in_LCH_space%29.jpg/960px-John_William_Waterhouse_-_The_Lady_of_Shalott_-_Google_Art_Project_%28derivative_work_-_AutoContrast_edit_in_LCH_space%29.jpg', 'テニスンの詩に登場する、呪いにより塔に閉じこめられた乙女が、ランスロットを慕って小舟でキャメロットへ向かう場面を描いた1888年の作品で、ロンドンのテート・ブリテンが所蔵します。ろうそくの火が消えかけ、鎖を解いた舟がゆっくり流れ出す一瞬に、乙女の運命が重ねられています。水辺の葦や織物の模様まで細かく描き込まれ、ラファエル前派の精緻な自然描写を受け継いだ画面です。ウォーターハウスはこの主題を生涯に何度も描きました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:John_William_Waterhouse_-_The_Lady_of_Shalott_-_Google_Art_Project_(derivative_work_-_AutoContrast_edit_in_LCH_space).jpg'),
    (2, '夜の梅', '鈴木春信', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/MET_DP119555.jpg/960px-MET_DP119555.jpg', '1766年ごろの鈴木春信の錦絵で、ニューヨークのメトロポリタン美術館が所蔵します。春信は多色摺りの木版画「錦絵」の誕生に深く関わった絵師です。夜の闇を一面の黒で摺り、灯りを手にした娘が闇に浮かぶ白梅を見上げる姿を、細くしなやかな線で描いています。墨一色の背景が花の白さと娘の着物の色を引き立て、静かな夜の気配と梅の香りまで感じさせる、春信らしい詩情に満ちた一枚です。', 'CC0', null, 'https://commons.wikimedia.org/wiki/File:MET_DP119555.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
